"""Validation rules migrated from legacy/opportunity_rules.vrl."""

from decimal import Decimal
from typing import Any


def _value(row: dict | None, column: str) -> Any:
    """Return a field value, treating missing and None values as empty."""
    if row is None:
        return ""
    value = row.get(column, "")
    return "" if value is None else value


def _nvl(value: Any, default: Any) -> Any:
    """Implement legacy NVL semantics."""
    return default if value is None or value == "" else value


def _number(value: Any) -> Decimal:
    """Coerce a legacy NUMBER value for numeric comparison."""
    if value is None or value == "":
        return Decimal(0)
    if isinstance(value, Decimal):
        return value
    return Decimal(str(value))


def _text(value: Any) -> str:
    """Coerce a text or date value to its legacy string representation."""
    return "" if value is None else str(value)


def _date_gte(left: Any, right: Any) -> bool:
    """Perform legacy YYYYMMDD ordering with the null-date sentinel."""
    left_text = _text(left)
    right_text = _text(right)
    if left_text == "00000000" or right_text == "00000000":
        return False
    return left_text >= right_text


def _failure(code: str, message: str, severity: str = "BLOCK") -> dict:
    return {
        "code": code,
        "message": message,
        "severity": severity,
    }


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    """Evaluate all applicable opportunity rules in legacy rule-file order."""
    errors: list[dict] = []

    if event in ("INSERT", "UPDATE"):
        # OPP-001
        if not (_number(_nvl(_value(record, "AMT"), 0)) >= Decimal(0)):
            errors.append(_failure("E3001", "Amount negative"))

        # OPP-002
        if not (
            not (
                _text(_value(record, "STAT_CD")) == "W"
                and _number(_nvl(_value(record, "AMT"), 0)) == Decimal(0)
            )
        ):
            errors.append(
                _failure("E3002", "Won opportunity requires amount")
            )

        # OPP-003
        if not (
            not (
                _text(_value(record, "STAT_CD")) == "L"
                and _text(_value(record, "LOST_RSN")) == ""
            )
        ):
            errors.append(_failure("E3003", "Lost reason required"))

        # OPP-004
        if not (
            not (
                _text(_value(record, "STAT_CD")) == "W"
                and _text(_value(record, "CLOSE_DT")) == "00000000"
            )
        ):
            errors.append(
                _failure("E3004", "Won opportunity requires close date")
            )

    if event == "UPDATE":
        # OPP-005
        if not (
            not (
                _text(_value(old, "STAT_CD")) == "W"
                and _text(_value(record, "STAT_CD")) != "W"
            )
        ):
            errors.append(
                _failure("E3005", "Cannot reopen a won opportunity")
            )

    if event in ("INSERT", "UPDATE"):
        # OPP-006
        status = _text(_value(record, "STAT_CD"))
        stage_percent = _number(_value(record, "STAGE_PCT"))
        stage_is_consistent = (
            (status == "P" and stage_percent == Decimal(10))
            or (status == "Q" and stage_percent == Decimal(25))
            or (status == "N" and stage_percent == Decimal(60))
            or (status == "W" and stage_percent == Decimal(100))
            or (status == "L" and stage_percent == Decimal(0))
        )
        if not stage_is_consistent:
            errors.append(
                _failure("E3006", "Stage percent inconsistent with status")
            )

    if event == "INSERT":
        # OPP-007
        close_date = _text(_value(record, "CLOSE_DT"))
        if not (
            close_date == "00000000"
            or _date_gte(close_date, today)
        ):
            errors.append(
                _failure("E3007", "Close date in past", severity="WARN")
            )

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return whether at least one collected validation failure is blocking."""
    return any(error.get("severity") == "BLOCK" for error in errors)
